def copy_primary_equipment_to_standards(apps, schema_editor):
    CalibrationLog = apps.get_model('core', 'CalibrationLog')
    for log in CalibrationLog.objects.exclude(primary_equipment__isnull=True):
        if log.primary_equipment_id:
            log.standards.add(log.primary_equipment_id)


def seed_scope_abbreviations(apps, schema_editor):
    CalibrationType = apps.get_model('core', 'CalibrationType')
    seeds = {
        'general': 'GCAL',
        'pressure': 'PCAL',
        'temperature': 'TCAL',
    }
    for scope in CalibrationType.objects.all():
        if not (scope.abbreviation or '').strip():
            name = (scope.name or '').lower()
            abbr = None
            for key, val in seeds.items():
                if key in name:
                    abbr = val
                    break
            if abbr is None:
                abbr = ''.join(w[0] for w in (scope.name or '').split() if w).upper() or 'SCOPE'
            if CalibrationType.objects.filter(abbreviation__iexact=abbr).exclude(pk=scope.pk).exists():
                abbr = f'{abbr}{scope.pk}'
            scope.abbreviation = abbr
            scope.save(update_fields=['abbreviation'])


